import{_ as e,o,c as a,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"1992年 · 价值投资的本源","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1992年.md","filePath":"05_quotes/by-year/1992年.md"}'),r={name:"05_quotes/by-year/1992年.md"};function u(q,t,c,s,_,b){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="_1992年-·-价值投资的本源" tabindex="-1">1992年 · 价值投资的本源 <a class="header-anchor" href="#_1992年-·-价值投资的本源" aria-label="Permalink to &quot;1992年 · 价值投资的本源&quot;">​</a></h1><blockquote><p>&quot;练习不会完美；练习会使动作固化。此后，我修改了策略，尝试以合理价格购买好企业，而不是以好价格购买合理企业。&quot;——巴菲特（62岁）</p></blockquote><p>本页收录1992年致股东信中的经典语录。巴菲特在这一年系统阐述了价值投资的本源——内在价值是未来现金流的折现，并深入批判了股票期权制度的痼疾。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;任何股票、债券或企业的价值，由在资产剩余寿命期间预期发生的现金流入和流出——以适当的利率折现——决定。这是最根本的价值公式。&quot;</p></blockquote><blockquote><p>&quot;成长始终是价值计算的一个组成部分。在我们看来，&#39;价值投资&#39;这个词本身就是多余的。如果不是寻求至少足以证明支付金额合理的价值，什么是&#39;投资&#39;？&quot;</p></blockquote><blockquote><p>&quot;最好的企业，是在很长一段时间内能够以非常高的回报率使用大量增量资本的企业。最差的企业，是必须始终以非常低的回报率使用越来越多资本的企业。&quot;</p></blockquote><blockquote><p>&quot;我们计算一只普通股的价值只略高于其价格，我们就不感兴趣购买。本·格雷厄姆如此强烈强调的这一安全边际原则，是投资成功的基石。&quot;</p></blockquote><blockquote><p>&quot;当我试图亲吻蟾蜍时，我期待一个童话故事作为结果。不幸的是，蟾蜍就是蟾蜍。练习不会完美；练习会使动作固化。&quot;</p></blockquote><blockquote><p>&quot;如果期权不是一种薪酬形式，那它们是什么？如果薪酬不是费用，那它是什么？如果费用不应该计入收益计算，那它们应该去哪里？&quot;</p></blockquote><blockquote><p>&quot;大多数分析师认为他们必须在&#39;价值&#39;和&#39;成长&#39;两种方法之间做出选择。我们认为这是模糊思维，两种方法紧密相连，成长始终是价值计算的一个组成部分。&quot;</p></blockquote><blockquote><p>&quot;我们选择可交易的股权证券的方式，与我们评估整体收购企业的方式相同。我们希望该企业是：我们可以理解的；具有良好的长期前景的；由诚实和有能力的人经营的；以非常有吸引力的价格可获得的。&quot;</p></blockquote><blockquote><p>&quot;我们不喜欢短期预测，市场预测是毒药，应该锁在安全的地方，远离儿童，也远离在市场上表现得像儿童的成年人。&quot;</p></blockquote><blockquote><p>&quot;在能力圈内坚持做简单的事。当一根针就摆在眼前时，为什么要大海捞针呢？&quot;</p></blockquote><blockquote><p>&quot;近似正确胜过精确错误。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1992年伯克希尔每股账面价值增长20.3%，净资产增加15.2亿美元。巴菲特从所罗门兄弟临时董事长职位卸任，在年度信中完成了对所罗门危机的复盘。收购了中央州赔偿公司（82%股权），年保费约9000万美元。保险浮存金成本仅4.76%，长期国债收益率7.39%，连续二十多年低于国债利率。安德鲁飓风造成行业史上最大保险损失，伯克希尔赔付约1.25亿美元，正好等于当年超级巨灾保费收入。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1992年-翻译-·-01-letters-1992年-核心总结-·-01-letters-1992年-思维导图" tabindex="-1"><a href="/01_letters/1992年/翻译">01_letters/1992年/翻译</a> · <a href="/01_letters/1992年/核心总结">01_letters/1992年/核心总结</a> · <a href="/01_letters/1992年/思维导图">01_letters/1992年/思维导图</a> <a class="header-anchor" href="#_01-letters-1992年-翻译-·-01-letters-1992年-核心总结-·-01-letters-1992年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1992年/翻译]] · [[→ 核心总结|01_letters/1992年/核心总结]] · [[→ 思维导图|01_letters/1992年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1992年/翻译">/01_letters/1992年/翻译</a></li></ul>',24)])])}const i=e(r,[["render",u]]);export{p as __pageData,i as default};
